exec(compile('"""Shared spatial model; deterministic heuristic planning, not a trained AI model."""\nimport json, math, random\nfrom collections import deque\nfrom pathlib import Path\nfrom geometry import geometry, inside, fits, COLORS, SIZES\n\nSTRATEGIES={\n \'동선 균형형\': {\'spread\':1.,\'medical\':1.,\'travel\':1.5,\'target\':1.},\n \'응급 접근형\': {\'spread\':.6,\'medical\':4.,\'travel\':1.,\'target\':.7},\n \'혼잡 분산형\': {\'spread\':3.5,\'medical\':1.,\'travel\':.6,\'target\':.5},\n}\n\ndef demand(data):\n    weights={}\n    event=data.get(\'event_type\',\'축제\');age=data.get(\'age\',\'전 연령\');mood=data.get(\'mood\',\'활기찬\')\n    for name in data.get(\'facilities\',[]):\n        value={\'공연장\':1.8,\'푸드존\':1.4,\'체험 부스\':1.5,\'휴게 공간\':.7,\'안내센터\':.3,\'응급의료센터\':.04,\'화장실\':.5,\'굿즈 판매\':.6}.get(name,1.)\n        if event==\'공연\' and name==\'공연장\':value*=1.8\n        if event in (\'체험 행사\',\'박람회\') and name==\'체험 부스\':value*=1.7\n        if age in (\'어린이·가족\',\'청소년\') and name==\'체험 부스\':value*=1.4\n        if age==\'고령층\' and name==\'휴게 공간\':value*=1.7\n        if mood==\'차분한\' and name==\'휴게 공간\':value*=1.3\n        if mood==\'활기찬\' and name==\'공연장\':value*=1.2\n        if float(data.get(\'hours\',8))>=6 and name==\'푸드존\':value*=1.2\n        weights[name]=value\n    total=sum(weights.values()) or 1\n    return {n:v/total for n,v in weights.items()}\n\ndef spatial_grid(p):\n    w,h=math.ceil(p[\'width\']),math.ceil(p[\'depth\']);free=bytearray(w*h)\n    for y in range(h):\n        for x in range(w):\n            px,py=x+.5,y+.5\n            free[y*w+x]=inside(px,py,p[\'polygon\']) and not any(abs(px-z[\'x\'])<z[\'w\']/2+.7 and abs(py-z[\'y\'])<z[\'h\']/2+.7 for z in p[\'zones\'])\n    def nearest(x,y):\n        return min((i for i,f in enumerate(free) if f),key=lambda i:(i%w+.5-x)**2+(i//w+.5-y)**2,default=-1)\n    return w,h,free,nearest\n\ndef bfs(start,w,h,free):\n    prev=[-1]*len(free);dist=[-1]*len(free)\n    if start<0:return prev,dist\n    prev[start]=start;dist[start]=0;q=deque([start])\n    while q:\n        i=q.popleft();x,y=i%w,i//w\n        for nx,ny in ((x-1,y),(x+1,y),(x,y-1),(x,y+1)):\n            if 0<=nx<w and 0<=ny<h:\n                k=ny*w+nx\n                if free[k] and prev[k]<0:prev[k]=i;dist[k]=dist[i]+1;q.append(k)\n    return prev,dist\n\ndef analyze(p,data):\n    w,h,free,nearest=spatial_grid(p);gate=p[\'gates\'][0];start=nearest(gate[\'x\'],gate[\'y\']);prev,dist=bfs(start,w,h,free)\n    route_usage={};routes=[];connected=0;distance=0;shares=demand(data);nodes={}\n    for z in p[\'zones\']:\n        n=nearest(z[\'x\'],z[\'y\']-z[\'h\']/2-1.5);nodes[z[\'name\']]=n\n        reachable=n>=0 and dist[n]>=0;z[\'reachable\']=reachable;z[\'share\']=shares.get(z[\'name\'],0)\n        z[\'route_distance\']=dist[n] if reachable else None\n        if not reachable:continue\n        connected+=1;distance+=dist[n]*z[\'share\'];path=[];k=n\n        while k!=start:\n            path.append([k%w+.5,k//w+.5]);route_usage[k]=route_usage.get(k,0)+z[\'share\'];k=prev[k]\n        path.append([start%w+.5,start//w+.5]);routes.append({\'name\':z[\'name\'],\'points\':path[::-1]})\n    medical=nodes.get(\'응급의료센터\',-1);medical_distance=None\n    if medical>=0:\n        _,md=bfs(medical,w,h,free);vals=[md[n] for n in nodes.values() if n>=0 and n!=medical and md[n]>=0]\n        if vals: medical_distance=round(sum(vals)/len(vals),1)\n        medical_route=next((r[\'points\'] for r in routes if r[\'name\']==\'응급의료센터\'),[])\n    else:medical_route=[]\n    busy=[z for z in p[\'zones\'] if z[\'name\'] in (\'공연장\',\'푸드존\',\'체험 부스\',\'굿즈 판매\')]\n    separations=[math.dist((a[\'x\'],a[\'y\']),(b[\'x\'],b[\'y\'])) for i,a in enumerate(busy) for b in busy[i+1:]]\n    area=sum(inside(x+.5,y+.5,p[\'polygon\']) for y in range(h) for x in range(w));facility_area=sum(z[\'w\']*z[\'h\'] for z in p[\'zones\'])\n    p[\'routes\']=routes;p[\'medical_route\']=medical_route\n    p[\'metrics\']={\'connected\':connected,\'facilities\':len(p[\'zones\']),\'weighted_distance\':round(distance/max(.001,sum(z[\'share\'] for z in p[\'zones\'] if z[\'reachable\'])),1),\'medical_distance\':medical_distance,\'busy_separation\':round(sum(separations)/len(separations),1) if separations else 0,\'facility_area_pct\':round(100*facility_area/max(1,area),1),\'shared_route_pct\':round(100*sum(v>.6 for v in route_usage.values())/max(1,len(route_usage)),1),\'free_area\':int(sum(free))}\n    # Route overlap is a geometric demand proxy, not a physical crowd density prediction.\n    return p\n\ndef plan(data,analyze_routes=True):\n    w,h,poly,gates=geometry(data);placed=[];warnings=[];shares=demand(data)\n    strategy=data.get(\'strategy\',\'동선 균형형\');weights=STRATEGIES.get(strategy,STRATEGIES[\'동선 균형형\'])\n    anchors={\'공연장\':(.5,.8),\'푸드존\':(.8,.65),\'체험 부스\':(.23,.55),\'휴게 공간\':(.75,.3),\'응급의료센터\':(.22,.25),\'안내센터\':(.3,.15),\'화장실\':(.15,.72),\'굿즈 판매\':(.72,.8)}\n    saved=data.get(\'layout_positions\',{}) or {};clearance=float(data.get(\'clearance\',1.5));scale=max(.85,min(1.6,math.sqrt(max(100,int(data.get(\'visitors\',1200)))/1200)))\n    # Deliberately reserve central walking space; actual paths are subsequently solved on the free-space grid.\n    spine={\'x\':w*.46,\'y\':h*.48,\'w\':float(data.get(\'corridor_width\',3)),\'h\':h*.72}\n    cross={\'x\':w*.5,\'y\':h*.48,\'w\':w*.72,\'h\':float(data.get(\'corridor_width\',3))}\n    reserved=[spine,cross]\n    facilities=list(dict.fromkeys(data.get(\'facilities\',list(COLORS)[:6])))\n    facilities.sort(key=lambda n:(n not in (\'공연장\',\'응급의료센터\',\'안내센터\'),-shares.get(n,0)))\n    for name in facilities:\n        bw,bh=SIZES.get(name,(7,5));bw=round(bw*scale,1);bh=round(bh*scale,1)\n        ax,ay=anchors.get(name,(.5,.5));requested=saved.get(name)\n        if requested:ax,ay=map(float,requested)\n        def valid(pt):return fits(pt[0],pt[1],bw,bh,poly,placed+reserved,clearance)\n        candidates=[(ix,iy) for ix in range(2,int(w),3) for iy in range(2,int(h),3) if valid((ix,iy))]\n        target=(round(ax*w,8),round(ay*h,8))\n        def cost(pt):\n            x,y=pt;v=weights[\'target\']*math.dist(pt,target)/max(w,h)\n            v+=weights[\'travel\']*math.dist(pt,(gates[0][\'x\'],gates[0][\'y\']))*shares.get(name,0)/max(w,h)\n            if name==\'응급의료센터\':v+=weights[\'medical\']*(abs(x-spine[\'x\'])+math.dist(pt,(gates[0][\'x\'],gates[0][\'y\'])))/max(w,h)\n            if name in (\'공연장\',\'푸드존\',\'체험 부스\',\'굿즈 판매\'):\n                for z in placed:\n                    if z[\'name\'] in (\'공연장\',\'푸드존\',\'체험 부스\',\'굿즈 판매\'):v+=weights[\'spread\']*max(0,.45-math.dist(pt,(z[\'x\'],z[\'y\']))/max(w,h))\n            if name==\'안내센터\':v+=2*math.dist(pt,(gates[0][\'x\'],gates[0][\'y\']))/max(w,h)\n            return v\n        if requested and valid(target):x,y=target\n        elif candidates:\n            x,y=min(candidates,key=cost)\n            if requested:warnings.append(name+\'의 좌표를 외곽·시설 간격·주 통로 조건에 맞게 보정했습니다.\')\n        else:\n            warnings.append(name+\'의 배치 공간이 부족합니다. 크기를 늘리거나 시설 수를 줄이세요.\');continue\n        placed.append({\'name\':name,\'x\':x,\'y\':y,\'w\':bw,\'h\':bh,\'color\':COLORS.get(name,\'#64748b\'),\'share\':shares.get(name,0)})\n    p={\'width\':w,\'depth\':h,\'polygon\':poly,\'gates\':gates,\'zones\':placed,\'warnings\':warnings,\'shape\':data.get(\'venue_shape\',\'직사각형 (기본)\'),\'name\':data.get(\'name\',\'새 행사\'),\'visitors\':int(data.get(\'visitors\',1200)),\'strategy\':strategy,\'reserved\':reserved,\'seed\':int(data.get(\'seed\',42)),\'peak_fraction\':float(data.get(\'peak_fraction\',.25))}\n    if analyze_routes:\n        analyze(p,data)\n        for z in p[\'zones\']:\n            if not z[\'reachable\']:p[\'warnings\'].append(z[\'name\']+\'의 접근 경로가 연결되지 않습니다. 배치를 수정하세요.\')\n    return p\n\ndef actual_data(data,p=None):\n    p=p or plan(data);out=dict(data);out[\'layout_positions\']={z[\'name\']:(z[\'x\']/p[\'width\'],z[\'y\']/p[\'depth\']) for z in p[\'zones\']};return out\n\ndef optimize_layout_candidates(data):\n    result=[]\n    for name in STRATEGIES:\n        d=dict(data);d[\'strategy\']=name;d[\'layout_positions\']={};p=plan(d)\n        result.append({\'name\':name,\'positions\':actual_data(d,p)[\'layout_positions\'],\'metrics\':p[\'metrics\'],\'warnings\':p[\'warnings\'],\'plan\':p})\n    return result\n\ndef crowd_widget(data,p=None):\n    import streamlit.components.v1 as components\n    p=p or plan(data)\n    template=SPACE_VIEWER_HTML\n    components.html(template.replace(\'__PAYLOAD__\',json.dumps(p,ensure_ascii=False).replace(\'</\',\'<\\\\/\')),height=875,scrolling=True)\n\ndef make_layout_image(data,selected=None,path=None,p=None):\n    from geometry import make_layout_image as render\n    return render({**data,\'_resolved\':p or plan(data)},selected,path)\n', 'eventon_space', "exec"), _eventon_space_module.__dict__)

