import json, re, sqlite3
from datetime import date,time,datetime,timedelta
import streamlit as st
import storage
from eventon_space import COLORS, STRATEGIES, plan, demand, actual_data, crowd_widget, make_layout_image, optimize_layout_candidates
from report import build_report

st.set_page_config(page_title='Event ON · 행사 자동 설계',page_icon='🎪',layout='wide',initial_sidebar_state='expanded')
st.markdown('''<style>
.stApp{background:#f6f9fd;color:#17233b}[data-testid="stSidebar"]{background:#fff;border-right:1px solid #e2e8f0}.block-container{max-width:1500px;padding-top:2rem}h1{letter-spacing:-.045em;font-size:2.2rem!important}h2,h3{letter-spacing:-.02em}div.stButton>button,div.stDownloadButton>button{border-radius:10px}div[data-testid="stMetric"]{background:white;border:1px solid #e2e8f0;border-radius:14px;padding:15px}div[data-testid="stForm"]{background:white;border-radius:14px}.hero{background:linear-gradient(110deg,#eff6ff,#fff);border:1px solid #dbeafe;border-radius:18px;padding:27px;margin-bottom:20px}.hero small{font-weight:800;letter-spacing:2px;color:#2563eb}.hero h2{margin:10px 0;font-size:29px}.hero p{color:#64748b;line-height:1.7} [data-testid="stTabs"]{margin-top:15px}
</style>''',unsafe_allow_html=True)
DEFAULT={'name':'봄맞이 문화축제','event_type':'축제','purpose':'지역 주민 참여와 문화 체험','visitors':1200,'venue':'야외 축제장','venue_shape':'직사각형 (기본)','site_width':90,'site_depth':60,'event_date':(date.today()+timedelta(days=30)).isoformat(),'duration_days':1,'start_time':'10:00','end_time':'18:00','hours':8,'inside':'실외','mood':'활기찬','age':'전 연령','ticket':'무료','ticket_price':0,'budget':10000000,'facilities':list(COLORS)[:6],'extra':'','layout_positions':{},'strategy':'동선 균형형','clearance':1.5,'corridor_width':3,'peak_fraction':.25,'seed':42}
SHAPES=['직사각형 (기본)','정사각형','원형 광장','돔형 (지붕 있음)','타원형 경기장','L자형']
ENUMS={'event_type':['축제','박람회','공연','체험 행사','컨벤션·강연'],'venue':['야외 축제장','실내 전시장','컨벤션센터','공원·광장','실내 공연장'],'venue_shape':SHAPES,'inside':['실내','실외'],'mood':['활기찬','차분한','감성적인','전문적인','가족 친화적인','미래지향적인'],'age':['전 연령','어린이·가족','청소년','성인','고령층'],'ticket':['무료','유료'],'strategy':list(STRATEGIES)}
@st.cache_data(show_spinner=False,max_entries=32)
def cached_plan(d):return plan(d)
@st.cache_data(show_spinner=False,max_entries=8)
def candidates_for(d):return optimize_layout_candidates(d)

def valid_data(raw):
    if not isinstance(raw,dict):raise ValueError('JSON 최상위는 객체여야 합니다.')
    d={k:raw.get(k,v) for k,v in DEFAULT.items()}
    for k,choices in ENUMS.items():
        if d[k] not in choices:raise ValueError(k+' 선택값을 확인하세요.')
    for k,lo,hi in [('site_width',40,200),('site_depth',35,150),('visitors',1,100000),('duration_days',1,90),('budget',0,100000000000),('ticket_price',0,10000000),('clearance',1,3),('corridor_width',2,6),('peak_fraction',.1,.6),('seed',1,999999)]:
        if not lo<=float(d[k])<=hi:raise ValueError(k+' 범위를 확인하세요.')
        d[k]=int(d[k]) if k in ('visitors','duration_days','budget','ticket_price','seed') else float(d[k])
    if d['clearance'] not in (1.,1.5,2.,2.5,3.) or d['corridor_width'] not in (2.,3.,4.,5.,6.):raise ValueError('통로 폭·여유 간격 선택값을 확인하세요.')
    for k in ('name','purpose','extra'):
        if not isinstance(d[k],str) or len(d[k])>3000:raise ValueError(k+' 텍스트를 확인하세요.')
    if not d['name'].strip():raise ValueError('행사명이 필요합니다.')
    if not isinstance(d['facilities'],list) or not d['facilities'] or any(n not in COLORS for n in d['facilities']):raise ValueError('시설 목록을 확인하세요.')
    date.fromisoformat(d['event_date']);start=time.fromisoformat(d['start_time']);end=time.fromisoformat(d['end_time'])
    sh=start.hour+start.minute/60;eh=end.hour+end.minute/60;d['hours']=eh-sh if eh>sh else eh-sh+24
    if not isinstance(d['layout_positions'],dict):raise ValueError('좌표 객체를 확인하세요.')
    for name,pos in d['layout_positions'].items():
        if name not in COLORS or not isinstance(pos,(tuple,list)) or len(pos)!=2 or not all(0<=float(v)<=1 for v in pos):raise ValueError('시설 상대 좌표는 0~1이어야 합니다.')
    return d

def initialize():
    for key,value in [('user',None),('design',dict(DEFAULT)),('pid',None),('revision',0),('nav','홈')]:
        if key not in st.session_state:st.session_state[key]=value
initialize()
if 'pending_nav' in st.session_state: st.session_state.nav=st.session_state.pop('pending_nav')

def auth():
    st.markdown('<div class="hero"><small>EVENT ON</small><h2>아이디어를 행사 공간으로.</h2><p>행사 정보를 입력하고, 공간을 배치하고, 방문객 흐름을 확인하세요.</p></div>',unsafe_allow_html=True)
    a,b=st.columns(2,gap='large')
    with a:
        st.subheader('로그인')
        with st.form('login'):
            un=st.text_input('아이디',max_chars=40);pw=st.text_input('비밀번호',type='password')
            if st.form_submit_button('로그인',type='primary',use_container_width=True):
                now=datetime.now().timestamp()
                if now<st.session_state.get('locked_until',0):st.error('잠시 후 다시 시도해 주세요.')
                else:
                    user=storage.login(un.strip(),pw)
                    if user:st.session_state.user=user;st.session_state.login_failures=0;st.rerun()
                    else:
                        st.session_state.login_failures=st.session_state.get('login_failures',0)+1
                        if st.session_state.login_failures>=5:st.session_state.locked_until=now+60;st.session_state.login_failures=0
                        st.error('아이디 또는 비밀번호를 확인해 주세요.')
    with b:
        st.subheader('회원가입')
        with st.form('signup'):
            name=st.text_input('이름',max_chars=60);un=st.text_input('사용할 아이디',help='영문·숫자·밑줄 3~40자');pw=st.text_input('비밀번호 (8자 이상)',type='password');pw2=st.text_input('비밀번호 확인',type='password')
            if st.form_submit_button('계정 만들기',use_container_width=True):
                if not name.strip() or not re.fullmatch(r'[A-Za-z0-9_]{3,40}',un) or len(pw)<8 or pw!=pw2:st.error('이름·아이디 형식·비밀번호를 확인해 주세요.')
                else:
                    try:storage.register(un,pw,name.strip());st.success('가입 완료! 왼쪽에서 로그인하세요.')
                    except sqlite3.IntegrityError:st.error('이미 사용 중인 아이디입니다.')
    st.info('개발용 SQLite 버전입니다. Cloud 재배포·재시작 시 계정/프로젝트 파일이 유실될 수 있어 JSON 백업이 필요합니다. 실제 서비스에서는 외부 DB와 운영용 인증을 연결하세요.')
if not st.session_state.user:auth();st.stop()
user=storage.profile(st.session_state.user['username'])
if not user:st.session_state.user=None;st.rerun()
owner=user['username']

def apply(data,save=False,pid='keep'):
    data=valid_data(data);p=cached_plan(data);data=actual_data(data,p)
    st.session_state.design=data;st.session_state.revision+=1;st.session_state.pop('candidates',None);st.session_state.pop('pdf',None)
    if pid!='keep':st.session_state.pid=pid
    if save:st.session_state.pid=storage.save_project(owner,data,st.session_state.pid);st.session_state.flash='배치와 행사 정보를 저장했습니다.'
    st.rerun()

