    d=valid_data(storage.load_project(owner,pid));st.session_state.design=d;st.session_state.pid=pid;st.session_state.revision+=1;st.session_state.pop('candidates',None);st.session_state.pop('pdf',None);st.session_state.pending_nav='행사 설계';st.rerun()

